INSERT INTO `site_contents` (`id`, `content`, `created_at`, `updated_at`) VALUES (1,'{\"home\": {\"metrics\": [{\"label\": \"Project Selesai\", \"value\": \"AUTO_PROJECT_COUNT\"}, {\"label\": \"Disiplin Utama (Web / API / IoT)\", \"value\": \"03\"}, {\"label\": \"Fokus pada Clarity & Reliability\", \"value\": \"100%\"}], \"telemetry\": {\"title\": \"LIVE SYSTEM TELEMETRY\", \"live_label\": \"LIVE\", \"nodes_value\": \"NODES: ESP32-S3 / REST API / POSTGRES\", \"pause_label\": \"PAUSE\", \"latency_label\": \"PING LATENCY\", \"packets_label\": \"TELEMETRY PACKETS\", \"protocol_label\": \"PROTOCOL\", \"protocol_value\": \"MQTT / WS\", \"node_status_label\": \"NODE STATUS\", \"node_status_value\": \"ONLINE\"}, \"hero_title\": \"Membangun software yang terhubung dengan dunia nyata.\", \"tech_stack\": [\"Next.js\", \"React\", \"TypeScript\", \"Node.js\", \"Python\", \"ESP32 / IoT\", \"Docker\", \"PostgreSQL\", \"Tailwind CSS\"], \"stack_label\": \"CORE STACK:\", \"capabilities\": [{\"tag\": \"Frontend\", \"title\": \"Interface Engineering\", \"description\": \"Merancang antarmuka responsif dengan struktur visual yang jelas, interaksi yang konsisten, dan pengalaman yang tetap baik di berbagai perangkat.\"}, {\"tag\": \"API Systems\", \"title\": \"Backend & API\", \"description\": \"Merancang API, autentikasi, logika aplikasi, dan alur data dengan struktur yang modular dan mudah dikembangkan.\"}, {\"tag\": \"IoT\", \"title\": \"IoT Integration\", \"description\": \"Mengintegrasikan sensor, mikrokontroler, komunikasi data, backend, dan dashboard menjadi satu sistem yang dapat dipantau dan dikendalikan.\"}], \"hero_eyebrow\": \"FULL-STACK DEVELOPMENT / IoT / AI\", \"contact_title\": \"Punya sistem yang perlu dibuat lebih jelas?\", \"process_steps\": [{\"title\": \"Pahami masalah\", \"description\": \"Memahami pengguna, kebutuhan, batasan, dan tujuan sebelum menentukan solusi.\"}, {\"title\": \"Rancang sistem\", \"description\": \"Menentukan arsitektur, alur data, komponen, dan teknologi sebelum implementasi berkembang terlalu jauh.\"}, {\"title\": \"Bangun & iterasi\", \"description\": \"Mengembangkan fitur dalam bagian kecil, mengujinya, lalu memperbaiki berdasarkan hasil nyata.\"}, {\"title\": \"Uji & deploy\", \"description\": \"Memverifikasi fungsi penting, menangani edge case, lalu menyiapkan sistem untuk digunakan.\"}], \"process_title\": \"Dari pertanyaan yang tepat menuju sistem yang bekerja.\", \"profile_title\": \"Dari antarmuka hingga perangkat, satu sistem.\", \"project_types\": [{\"id\": \"web\", \"label\": \"Web App\", \"description\": \"Aplikasi web interaktif dengan performa tinggi\"}, {\"id\": \"iot\", \"label\": \"IoT & Hardware\", \"description\": \"Integrasi sensor, mikrokontroler & dashboard monitoring\"}, {\"id\": \"backend\", \"label\": \"Backend API\", \"description\": \"Arsitektur REST API, database & autentikasi aman\"}, {\"id\": \"fullstack\", \"label\": \"Full Stack System\", \"description\": \"Solusi lengkap dari frontend, API hingga sistem database\"}], \"principle_text\": \"Clarity first. Complexity stays behind the interface.\", \"contact_eyebrow\": \"MULAI DISKUSI / 05\", \"cv_action_label\": \"Lihat CV\", \"principle_label\": \"PRINCIPLE\", \"process_eyebrow\": \"PROSES ENGINEERING / 04\", \"profile_eyebrow\": \"TENTANG / KAPABILITAS \", \"hero_description\": \"Saya membangun aplikasi web, backend, dan sistem IoT dari antarmuka pengguna hingga API, database, deployment, dan integrasi perangkat.\", \"brief_focus_label\": \"FOKUS\", \"profile_discipline\": \"Full-Stack Development / IoT / AI\", \"brief_action_prefix\": \"Kirim brief\", \"brief_builder_label\": \"INTERACTIVE BRIEF BUILDER\", \"contact_description\": \"Ceritakan masalah, pengguna, dan konteks teknisnya. Kita mulai dengan memetakan langkah pertama yang paling masuk akal.\", \"process_description\": \"Setiap project dimulai dari memahami masalah, lalu menerjemahkannya menjadi keputusan desain dan teknis yang dapat diuji.\", \"selected_work_title\": \"Produk yang selesai berbicara lewat hasil.\", \"primary_action_label\": \"Lihat project\", \"profile_fallback_bio\": \"Saya bekerja di pertemuan antara interface, data, dan perangkat. Tujuannya sederhana: sistem kompleks tetap mudah dipahami oleh orang yang memakainya.\", \"selected_work_eyebrow\": \"PROJECT PILIHAN \", \"secondary_action_label\": \"Tentang saya\", \"selected_project_count\": 2, \"brief_expectation_label\": \"EKSPEKTASI\", \"brief_builder_description\": \"Pilih jenis proyek yang sedang Anda rencanakan:\", \"selected_work_description\": \"Contoh bagaimana keputusan antarmuka, struktur data, dan delivery disatukan menjadi produk yang dapat digunakan.\"}, \"global\": {\"nav_links\": [{\"href\": \"/\", \"label\": \"Beranda / Tentang\"}, {\"href\": \"/skills\", \"label\": \"Skills\"}, {\"href\": \"/projects\", \"label\": \"Project\"}, {\"href\": \"/contact\", \"label\": \"Kontak\"}], \"brand_name\": \"MARSHEL  ANDHINO S.  G\", \"footer_text\": \"BUILT WITH INTENT\", \"brand_aria_label\": \"Software dan Hardware, kembali ke beranda\", \"brand_descriptor\": \"/ SOFTWARE × HARDWARE\", \"availability_label\": \"TERBUKA UNTUK KOLABORASI\", \"resume_button_label\": \"CV\", \"mobile_menu_open_label\": \"Menu +\", \"mobile_menu_close_label\": \"Tutup ×\"}, \"resume\": {\"tag\": \"FULL-STACK & IOT ENGINEER\", \"eyebrow\": \"CURRICULUM VITAE / RESUME\", \"version\": \"PDF VERSION 2026.1\", \"highlights\": [{\"label\": \"PENDIDIKAN\", \"value\": \"Teknik Komputer / Computer Engineering\"}, {\"label\": \"DISIPLIN\", \"value\": \"Full-Stack, REST API, ESP32 / IoT\"}, {\"label\": \"FORMAT\", \"value\": \"Dokumen PDF Siap Cetak\"}], \"close_label\": \"Tutup\", \"description\": \"Ringkasan kualifikasi teknis, pengalaman proyek, arsitektur backend, dan rekayasa sistem IoT.\", \"download_label\": \"Unduh CV (PDF) ↓\", \"title_template\": \"{name} — Engineer Profile\", \"fallback_cv_url\": \"/Marshel_CV_Fullstack_IoT.pdf\", \"download_filename\": \"Marshel_CV_Engineer.pdf\"}, \"skills\": {\"cta_title\": \"Siap membangun sistem bersama?\", \"hero_title\": \"Kapabilitas & Spesifikasi Teknis\", \"milestones\": [{\"role\": \"Full Stack & IoT Systems Engineer\", \"period\": \"2024 - PRESENT\", \"description\": \"Spearheaded complex IoT interface integration, real-time telemetry dashboards, and Next.js web application architecture with high reliability.\"}, {\"role\": \"Frontend & Systems Developer\", \"period\": \"2023 - 2024\", \"description\": \"Built high-performance responsive web interfaces, state management architectures, and robust backend REST APIs.\"}, {\"role\": \"Hardware & Embedded Developer\", \"period\": \"2022 - 2023\", \"description\": \"Designed microcontroller sensor nodes, wireless telemetry protocols, and hardware-software integration loops.\"}], \"cta_eyebrow\": \"KOLABORASI\", \"hero_eyebrow\": \"TECHNICAL EXPERTISE / INDEX\", \"table_headers\": [\"TECHNOLOGY\", \"CATEGORY\", \"PROFICIENCY\", \"YEARS EQ.\"], \"timeline_title\": \"Milestones\", \"cta_description\": \"Lihat bagaimana kapabilitas teknis ini diterapkan pada produk dan proyek nyata.\", \"hero_description\": \"Membangun sistem digital yang andal, scalable, dan terintegrasi—dari arsitektur frontend modern, REST API backend, hingga komunikasi perangkat IoT dan hardware secara presisi.\", \"timeline_eyebrow\": \"TIMELINE \", \"competencies_title\": \"Core Competencies\", \"competencies_eyebrow\": \"CAPABILITIES \", \"contact_action_label\": \"Hubungi Saya\", \"specifications_title\": \"Technical Specifications\", \"projects_action_label\": \"Lihat Project →\", \"specifications_eyebrow\": \"SPECIFICATIONS \"}, \"contact\": {\"title\": \"Ceritakan sistem yang ingin dibuat lebih jelas.\", \"eyebrow\": \"CONTACT / START A CONVERSATION\", \"name_label\": \"Nama\", \"description\": \"Bagikan tujuan, pengguna, dan tantangan utamanya. Saya akan membantu memetakan langkah pertama yang masuk akal.\", \"email_label\": \"Email\", \"toast_error\": \"Gagal mengirim pesan. Silakan coba lagi.\", \"form_eyebrow\": \"PROJECT INTAKE\", \"submit_label\": \"Kirim pesan\", \"error_message\": \"Pesan gagal dikirim. Periksa koneksi lalu coba lagi.\", \"message_label\": \"Pesan\", \"toast_success\": \"Pesan berhasil dikirim ke Marshel!\", \"success_message\": \"Pesan berhasil dikirim. Terima kasih—saya akan meninjaunya segera.\", \"name_placeholder\": \"Masukkan nama\", \"submitting_label\": \"Mengirim…\", \"email_placeholder\": \"alamat@email.com\", \"availability_label\": \"● OPEN FOR SELECTED COLLABORATIONS\", \"message_placeholder\": \"Tujuan, pengguna, dan tantangan project\", \"prefill_focus_label\": \"Fokus Project\", \"prefill_detail_label\": \"Tujuan & Detail Project\", \"email_invalid_message\": \"Gunakan format email yang valid.\", \"name_required_message\": \"Nama wajib diisi.\", \"prefill_general_label\": \"Umum\", \"email_required_message\": \"Email wajib diisi.\", \"message_required_message\": \"Pesan wajib diisi.\"}, \"projects\": {\"hero_title\": \"Sistem dan produk yang sudah saya bangun.\", \"index_title\": \"Project pilihan\", \"filter_label\": \"FILTER PROJECT\", \"hero_eyebrow\": \"PROJECTS & SKILLS / INDEX\", \"index_eyebrow\": \"KARYA TERBARU\", \"displayed_suffix\": \"DITAMPILKAN\", \"hero_description\": \"Jelajahi karya berdasarkan kategori dan lihat teknologi yang digunakan pada setiap project.\", \"card_action_label\": \"Lihat studi kasus\", \"all_category_label\": \"Semua\", \"search_placeholder\": \"Cari project atau tech stack...\"}, \"project_detail\": {\"back_label\": \"Projects & Skills\", \"demo_label\": \"Live Demo\", \"github_label\": \"GitHub\", \"skills_label\": \"Skills\", \"about_eyebrow\": \"TENTANG PROJECT\", \"gallery_title\": \"Dokumentasi visual\", \"stack_eyebrow\": \"STACK & SKILLS\", \"category_label\": \"Category\", \"gallery_eyebrow\": \"PROJECT GALLERY\", \"architecture_title\": \"Alur & Arsitektur Teknis\", \"gallery_empty_title\": \"Galeri belum tersedia\", \"about_fallback_title\": \"Detail, keputusan, dan hasil project.\", \"architecture_eyebrow\": \"SYSTEM ARCHITECTURE / FLOW\", \"gallery_empty_message\": \"Project ini belum memiliki dokumentasi visual tambahan.\"}}','2026-08-13 13:25:06','2026-08-14 06:37:52');
